style.css:
@-moz-document domain("roblox.com") {
/* Game/app tiles */
    .game-card-container,
    .game-card,
    .game-card-thumb-container,
    .thumbnail-2d-container,
    .thumbnail-2d,
    .game-card-thumb {
        background-color: #ffe6f0 !important; /* light pink background */
        border-radius: 8px !important;       /* smoother corners */
    }

    /* Optional: add a soft pink border */
    .game-card-container {
        border: 2px solid #ffb6c1 !important; /* medium pink */
    }

    /* Optional: hover effect */
    .game-card-container:hover {
        background-color: #ffccdd !important; /* darker pink on hover */
    }
}
